const REF_MAP: Record<string, ResearchReference> = Object.fromEntries(REFERENCES.map((r) => [r.id, r]));

export function getReference(id: string): ResearchReference | undefined {
  return REF_MAP[id];
}

export function getReferences(ids: string[]): ResearchReference[] {
  return ids.map((id) => REF_MAP[id]).filter((r): r is ResearchReference => Boolean(r));
}
